"use strict";
(()=>{const L=window.Lab;if(!L||!L.$('second-order-lab'))return;
L.init(['damping','position','velocity'],()=>{const b=L.range('damping'),x0=L.range('position'),v0=L.range('velocity'),state=t=>L.homogeneous(b,x0,v0,t),g=L.$('drawing');g.replaceChildren();const upper=L.svg('g'),lower=L.svg('g',{transform:'translate(0,275)'});g.append(upper,lower);L.plot(upper,[{fn:t=>state(t).x}],{yMin:-1.5,yMax:1.5,height:270});L.plot(lower,[{fn:t=>state(t).v,color:'#cf604b'}],{yMin:-3,yMax:3,yLabel:'速度 v（m/s）',height:270});const s=state(1),e=.5*s.v*s.v+2*s.x*s.x;let type=b===0?'無阻尼':b<4?'欠阻尼':b===4?'臨界阻尼':'過阻尼';L.text('result-primary',L.fmt(s.x)+' m');L.text('result-secondary',L.fmt(s.v)+' m/s');L.text('feedback',type+'：起點 x₀='+L.fmt(x0)+' m、v₀='+L.fmt(v0)+' m/s；1 s 時能量 E = ½mv² + ½kx² = '+L.fmt(e)+' J。'+(x0===0&&v0===0?'初始位置與速度都是零，沒有外力，所以小車一直停在平衡位置。':b===0?'沒有耗能項，總機械能不隨時間衰減。':b<4?'回復與慣性讓車越過原點，阻力逐步耗能。':b===4?'在本固定 m、k 下恰為重根；不振盪。':'兩個實衰減率不同，阻力太大會讓返回變慢。')+' 圖的時間與縱軸固定，位置、速度分軸顯示。');});})();
